const ALL = ['10c00', '10c03', '10c06', '10c07', '10c09', '10c0b', '10c0d', '10c0f', '10c11', '10c13', '10c14', '10c16', '10c18', '10c1a', '10c1c', '10c1e', '10c20', '10c21', '10c22', '10c23', '10c24', '10c26', '10c28', '10c2a', '10c2d', '10c2f', '10c30', '10c31', '10c32', '10c34', '10c36', '10c38', '10c3a', '10c3c', '10c3d', '10c3e', '10c3f', '10c41', '10c43', '10c45', '10c47', '10c48']; // Orhun harfleri (Unicode ORKHON)
// taş yazıt (dikilitaş). rows: dikey sütun sayısı, rp: görünen harf oranı
function stele(ctx, x, y, s, rp = 1, lt = 0, seed = 1) {
  ctx.save(); ctx.translate(x, y); ctx.scale(s, s);
  shape(ctx, [[-170, 0], [-180, 60], [180, 60], [170, 0]], '#7d7a70', C.ink, 6, .5);
  shape(ctx, [[-130, 0], [-136, -520], [-110, -600], [-40, -640], [40, -640], [110, -600], [136, -520], [130, 0]], '#a9a497', C.ink, 7, .8);
  line(ctx, [[-90, -560], [-60, -520], [-74, -470]], 'rgba(42,29,21,.35)', 3, .5); line(ctx, [[96, -180], [70, -140]], 'rgba(42,29,21,.35)', 3, .5);
  const r = rng(seed); const cols = 4, per = 9; let i = 0; const tot = cols * per; const shown = Math.floor(rp * tot);
  for (let c = 0; c < cols; c++) for (let k = 0; k < per; k++, i++) { if (i >= shown) continue; const cp = ALL[Math.floor(r() * ALL.length)];
    const cx = 75 - c * 50, cy = -540 + k * 56; ctx.save(); ctx.translate(cx, cy); ctx.rotate(-Math.PI / 2); rune(ctx, cp, -18, 14, 44, '#3a342c', true); ctx.restore(); }
  ctx.restore();
}
function chips(ctx, lt, x, y, t0 = 0) {
  for (let i = 0; i < 10; i++) { const k = ((lt - t0) * 2.2 + hash(i)) % 1; const a = -Math.PI / 2 + (hash(i + 3) - .5) * 2.4; const r = k * 140;
    ctx.globalAlpha = 1 - k; shape(ctx, [[x + Math.cos(a) * r, y + Math.sin(a) * r + k * k * 90], [x + Math.cos(a) * r + 9, y + Math.sin(a) * r + 4 + k * k * 90], [x + Math.cos(a) * r + 2, y + Math.sin(a) * r + 10 + k * k * 90]], '#cfc9bb', C.ink, 2, .2); }
  ctx.globalAlpha = 1;
}
function chisel(ctx, x, y, s, hit) {
  ctx.save(); ctx.translate(x, y); ctx.scale(s, s); ctx.rotate(-.6);
  shape(ctx, [[-10, 0], [10, 0], [8, -150], [-8, -150]], '#9aa3a8', C.ink, 4, .3); shape(ctx, [[-6, 0], [6, 0], [0, 20]], '#cfd3d6', C.ink, 3, .2);
  shape(ctx, [[-16, -150], [16, -150], [16, -240], [-16, -240]], '#6e4a2c', C.ink, 4, .3);
  ctx.restore();
  const hy = -lerp(260, 240, hit); ctx.save(); ctx.translate(x, y); ctx.scale(s, s); ctx.rotate(-.6);
  ctx.translate(0, hy - 40 * (1 - hit)); ctx.rotate((1 - hit) * -.5);
  shape(ctx, [[-60, -30], [60, -30], [60, 30], [-60, 30]], '#7d7a70', C.ink, 4, .3); line(ctx, [[60, 0], [190, 0]], '#6e4a2c', 14, .2);
  ctx.restore();
}
